mapper.insert:
INSERT IGNORE INTO material_processing_job (
    id, upload_session_id, revision_id, stage, work_key, input_fingerprint, priority,
    status, attempt, not_before, lease_owner, lease_until, fence_token, last_error_code, payload_json
) VALUES (
    #{id}, #{uploadSessionId}, #{revisionId}, #{stage}, #{workKey}, #{inputFingerprint}, #{priority},
    #{status}, #{attempt}, #{notBefore}, #{leaseOwner}, #{leaseUntil}, #{fenceToken},
    #{lastErrorCode}, #{payloadJson}
)

mapper.select:
SELECT * FROM material_processing_job WHERE status IN ('QUEUED', 'RETRY') AND not_before <= #{now}
AND stage IN #{stage}
AND (revision_id IS NULL OR stage IN ('BUILD_COMPATIBILITY_PROJECTION', 'REPAIR_VECTOR_BATCH') OR EXISTS ( SELECT 1 FROM material_processing_revision r WHERE r.id = material_processing_job.revision_id AND r.fingerprint = #{processingFingerprint} ) OR EXISTS ( SELECT 1 FROM retrieval_revision_vector_projection rv WHERE material_processing_job.stage IN ('EMBED_CHUNK_BATCHES', 'UPSERT_VECTOR_BATCHES', 'VERIFY_PROJECTION_MANIFEST', 'PUBLISH_REVISION') AND rv.revision_id = material_processing_job.revision_id AND rv.index_generation_id = #{projectionGenerationId} AND rv.projection_role = 'COMPATIBILITY' )) AND (stage != 'PROMOTE_ORIGINAL' OR EXISTS ( SELECT 1 FROM material_upload_session u JOIN material_processing_revision r ON r.id = u.processing_revision_id WHERE u.id = material_processing_job.upload_session_id AND r.fingerprint = #{processingFingerprint} ))
AND ( stage NOT IN ('BUILD_LEXICAL_PROJECTION', 'EMBED_CHUNK_BATCHES', 'UPSERT_VECTOR_BATCHES', 'VERIFY_PROJECTION_MANIFEST', 'PUBLISH_REVISION', 'BUILD_COMPATIBILITY_PROJECTION', 'REPAIR_VECTOR_BATCH') OR (stage = 'BUILD_LEXICAL_PROJECTION' AND ( NOT EXISTS (SELECT 1 FROM rag_index_generation active WHERE active.state = 'ACTIVE') OR EXISTS (SELECT 1 FROM rag_index_generation active WHERE active.state = 'ACTIVE' AND active.id = #{projectionGenerationId}) )) OR (stage != 'BUILD_LEXICAL_PROJECTION' AND (work_key = CONCAT('ig:', #{projectionGenerationId}) OR work_key LIKE CONCAT('ig:', #{projectionGenerationId}, ':%')) AND EXISTS (SELECT 1 FROM rag_index_generation routed WHERE routed.id = #{projectionGenerationId} AND routed.state IN ('BUILDING', 'SHADOW', 'ACTIVE'))) )
ORDER BY priority DESC, created_at ASC LIMIT 1 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE material_processing_job
SET lease_until = #{leaseUntil}
WHERE id = #{id} AND status = 'RUNNING'
  AND lease_owner = #{workerId} AND fence_token = #{fenceToken}
  AND lease_until > UTC_TIMESTAMP(3)
  AND lease_until > #{now}

UPDATE material_processing_job
SET status = 'RETRY', not_before = #{now}, last_error_code = 'LEASE_EXPIRED',
    lease_owner = NULL, lease_until = NULL
WHERE status = 'RUNNING' AND lease_until <= #{now}
ORDER BY lease_until ASC
LIMIT #{limit}
